import os
import re
from pathlib import Path
from urllib.parse import quote_plus

import requests
from fastapi import FastAPI
from fastapi.middleware.cors import CORSMiddleware
from fastapi.responses import HTMLResponse
from pydantic import BaseModel

BASE_DIR = Path(__file__).resolve().parent
CHAT_URL = os.getenv("CHAT_URL", "http://127.0.0.1:8081/v1/chat/completions")
CHAT_MODEL = os.getenv("CHAT_MODEL", "qwen3-0.6b")
DATASET_DIR = Path(os.getenv("DATASET_DIR", str(BASE_DIR / "dataset")))

app = FastAPI(title="Offline Combat Aircraft AI")
app.add_middleware(
    CORSMiddleware,
    allow_origins=["*"],
    allow_credentials=True,
    allow_methods=["*"],
    allow_headers=["*"],
)

class ChatRequest(BaseModel):
    prompt: str
    search_web: bool = False


def local_context(prompt: str) -> str:
    words = set(re.findall(r"[a-z0-9]+", prompt.lower()))
    paragraphs = []
    for text_file in DATASET_DIR.glob("*.txt"):
        if text_file.name in {"extracted_book_text.txt", "extracted_book_text_elon.txt"}:
            continue
        content = text_file.read_text(encoding="utf-8", errors="replace")
        paragraphs.extend(content.split("\n\n"))
    ranked = sorted(
        (item.strip() for item in paragraphs if item.strip()),
        key=lambda item: len(words & set(re.findall(r"[a-z0-9]+", item.lower()))),
        reverse=True,
    )
    return "\n\n".join(ranked[:3]) or "No approved local dataset is configured."


def search_online(prompt: str) -> str:
    response = requests.get(
        "https://html.duckduckgo.com/html/?q=" + quote_plus(prompt),
        headers={"User-Agent": "CombatAircraftAI/1.0"},
        timeout=15,
    )
    response.raise_for_status()
    matches = re.findall(
        r'class="result__a"[^>]*>(.*?)</a>.*?class="result__snippet"[^>]*>(.*?)</a?>',
        response.text,
        flags=re.DOTALL,
    )
    results = []
    for title, snippet in matches[:5]:
        clean_title = re.sub(r"<.*?>", "", title).strip()
        clean_snippet = re.sub(r"<.*?>", "", snippet).strip()
        results.append(f"Title: {clean_title}\nSnippet: {clean_snippet}")
    return "\n\n".join(results) or "No permitted web results were returned."


def generate_reply(prompt: str, context: str, online: bool) -> str:
    source = "permitted web snippets" if online else "the local aircraft dataset"
    response = requests.post(
        CHAT_URL,
        json={
            "model": CHAT_MODEL,
            "messages": [
                {
                    "role": "system",
                    "content": (
                        f"You are a precise combat aircraft assistant. Use only {source}. "
                        "If the answer is unavailable, say so clearly."
                    ),
                },
                {"role": "user", "content": f"CONTEXT:\n{context}\n\nQUESTION:\n{prompt}"},
            ],
            "stream": False,
            "temperature": 0.15,
        },
        timeout=180,
    )
    response.raise_for_status()
    return response.json()["choices"][0]["message"]["content"].strip()


@app.get("/", response_class=HTMLResponse)
async def homepage():
    return (BASE_DIR / "index.html").read_text(encoding="utf-8")


@app.post("/ask")
async def ask_ai(request: ChatRequest):
    prompt = request.prompt.strip()
    if not prompt:
        return {"reply": "Please enter a question."}
    try:
        context = search_online(prompt) if request.search_web else local_context(prompt)
        return {"reply": generate_reply(prompt, context, request.search_web)}
    except requests.RequestException as error:
        return {"reply": f"Local service unavailable: {error}"}


if __name__ == "__main__":
    import uvicorn

    uvicorn.run(app, host="127.0.0.1", port=8080)

