import os
import re
from pathlib import Path

import requests

BASE_DIR = Path(__file__).resolve().parent
DATASET_DIR = BASE_DIR / "dataset"
BOOK_TEXT_PATH = BASE_DIR / "extracted_book_text.txt"
OCR_TEXT_PATH = DATASET_DIR / "combat_aircraft_layout.txt"
VECTOR_DB_PATH = Path(os.getenv("VECTOR_DB_PATH", str(BASE_DIR / "aircraft_vector_db_clean")))
COLLECTION_NAME = "combat_aircraft"
EMBED_URL = os.getenv("EMBED_URL", "http://127.0.0.1:8082/embedding")

PAGE_MARKER = re.compile(
    r"(?im)^\s*(?:---\s*PAGE\s+(\d+)\s*---|##\s*Page\s+(\d+)\s*)\s*$"
)
WORDS_PER_CHUNK = 420
CHUNK_OVERLAP = 70


def parse_pages(text: str) -> dict[int, str]:
    markers = list(PAGE_MARKER.finditer(text))
    if not markers:
        return {1: text.strip()} if text.strip() else {}

    pages = {}
    for index, marker in enumerate(markers):
        page_number = int(marker.group(1) or marker.group(2))
        end = markers[index + 1].start() if index + 1 < len(markers) else len(text)
        page_text = text[marker.end():end].strip()
        if page_text:
            pages[page_number] = page_text
    return pages


def load_book_pages() -> dict[int, str]:
    pages = {}
    if BOOK_TEXT_PATH.is_file():
        pages.update(parse_pages(BOOK_TEXT_PATH.read_text(encoding="utf-8", errors="replace")))
    if OCR_TEXT_PATH.is_file():
        ocr_pages = parse_pages(OCR_TEXT_PATH.read_text(encoding="utf-8", errors="replace"))
        pages.update(ocr_pages)
    if not pages:
        raise FileNotFoundError(
            f"No book text found. Run OCR on book_images or provide {BOOK_TEXT_PATH}."
        )
    return pages


def chunk_pages(pages: dict[int, str]) -> list[tuple[str, str, dict[str, int | str]]]:
    chunks = []
    for page_number, text in sorted(pages.items()):
        words = text.split()
        if not words:
            continue
        start = 0
        chunk_number = 0
        while start < len(words):
            end = min(start + WORDS_PER_CHUNK, len(words))
            chunk = " ".join(words[start:end]).strip()
            if chunk:
                chunks.append(
                    (
                        f"page_{page_number:04d}_chunk_{chunk_number:02d}",
                        chunk,
                        {"page": page_number, "source": OCR_TEXT_PATH.name if OCR_TEXT_PATH.is_file() else BOOK_TEXT_PATH.name},
                    )
                )
            if end == len(words):
                break
            start = end - CHUNK_OVERLAP
            chunk_number += 1
    return chunks


def embed_text(text: str) -> list[float]:
    response = requests.post(EMBED_URL, json={"content": text}, timeout=60)
    response.raise_for_status()
    payload = response.json()
    if isinstance(payload, dict) and isinstance(payload.get("embedding"), list):
        vector = payload["embedding"]
    elif (
        isinstance(payload, dict)
        and isinstance(payload.get("data"), list)
        and payload["data"]
        and isinstance(payload["data"][0], dict)
    ):
        vector = payload["data"][0].get("embedding")
    else:
        vector = None
    if not isinstance(vector, list) or not vector:
        raise ValueError("Embedding service response did not contain a non-empty embedding vector.")
    if any(not isinstance(value, (int, float)) for value in vector):
        raise ValueError("Embedding service returned non-numeric vector values.")
    return [float(value) for value in vector]

