            "url": _clean(item.get("url")),
            "content": _clean(item.get("content")),
            "published": _clean(item.get("published_date")),
        }
        if _valid_result(result) and _relevant(query, result):
            results.append(result)
    return results


def search_online(query: str, limit: int = 6) -> list[dict[str, str]]:
    tavily_api_key = os.getenv("TAVILY_API_KEY")
    if tavily_api_key:
        results = _tavily_search(query, limit, tavily_api_key)
        provider = "Tavily"
    else:
        results = _bing_search(query, limit)
        provider = "Bing"
    if not results:
        raise ValueError(
            f"{provider} returned no search results relevant to your question. "
            "Try rephrasing it with specific names or keywords."
        )
    return results

