import argparse
import hashlib
import re
from urllib.parse import parse_qsl, urlencode, urlsplit, urlunsplit

import chromadb
import requests

from book_rag import VECTOR_DB_PATH, local_embedding_function

DEFAULT_DATASET_URL = (
    "https://datasets-server.huggingface.co/rows"
    "?dataset=nielsprovos%2Fworld-history-1500-qa"
    "&config=default&split=train&offset=0&length=100"
)
DEFAULT_COLLECTION = "history_sample"
MAX_PAGE_SIZE = 100
WORDS_PER_CHUNK = 100
CHUNK_OVERLAP = 20


def extract_documents(row: dict) -> list[tuple[str, str]]:
    documents = []
    metadata = row.get("metadata")
    dataset_title = metadata.get("dataset_name") if isinstance(metadata, dict) else None
    title = str(row.get("title") or row.get("name") or dataset_title or "History").strip()
    qa_pairs = row.get("qa_pairs")
    if isinstance(qa_pairs, list):
        for pair in qa_pairs:
            if not isinstance(pair, dict):
                continue
            question = pair.get("question")
            answer = pair.get("answer")
            if isinstance(question, str) and isinstance(answer, str):
                documents.extend((title, chunk) for chunk in split_qa(question, answer))
            else:
                documents.extend(extract_documents(pair))
        if documents:
            return documents

    question = row.get("question")
    answer = row.get("answer")
    if isinstance(question, str) and isinstance(answer, str):
        return [(title, chunk) for chunk in split_qa(question, answer)]

    for field in ("passage", "context", "text", "content"):
        text = row.get(field)
        if isinstance(text, str) and text.strip():
            return [(title, chunk) for chunk in split_text(text.strip())]

    for field in ("data", "documents", "items", "records"):
        nested = row.get(field)
        if isinstance(nested, list):
            for item in nested:
                if isinstance(item, dict):
                    documents.extend(extract_documents(item))
            if documents:
                return documents

    return []


def split_text(text: str) -> list[str]:
    words = text.split()
    chunks = []
    start = 0
    while start < len(words):
        end = min(start + WORDS_PER_CHUNK, len(words))
        chunks.append(" ".join(words[start:end]))
        if end == len(words):
            break
        start = end - CHUNK_OVERLAP
    return chunks


def split_qa(question: str, answer: str) -> list[str]:
    prefix = f"Question: {question.strip()}\nAnswer:"
    prefix_words = prefix.split()
    answer_words = answer.split()
    answer_chunk_size = max(20, WORDS_PER_CHUNK - len(prefix_words))
    overlap = min(CHUNK_OVERLAP, answer_chunk_size - 1)
    chunks = []
    start = 0
    while start < len(answer_words):
        end = min(start + answer_chunk_size, len(answer_words))
        chunks.append(f"{prefix} {' '.join(answer_words[start:end])}".strip())
        if end == len(answer_words):
            break
        start = end - overlap
    return chunks


def fetch_documents(dataset_url: str, limit: int) -> list[tuple[str, str, str]]:
    documents = []
    offset = 0
    while len(documents) < limit:
        length = min(MAX_PAGE_SIZE, limit - len(documents))
        parts = urlsplit(dataset_url)
        query = dict(parse_qsl(parts.query, keep_blank_values=True))
        query.update(offset=str(offset), length=str(length))
        paged_url = urlunsplit(parts._replace(query=urlencode(query)))
        response = requests.get(paged_url, timeout=60)
        response.raise_for_status()
        payload = response.json()
        rows = payload.get("rows")
        if not isinstance(rows, list):
            raise ValueError("Dataset API response must contain a 'rows' list.")
        if not rows:
            break

        for item in rows:
            if not isinstance(item, dict) or not isinstance(item.get("row"), dict):
                continue
            row_index = int(item.get("row_idx", offset))
            row_documents = extract_documents(item["row"])
            for chunk_index, (title, text) in enumerate(row_documents):
                document_id = f"row_{row_index}_chunk_{chunk_index}"
                documents.append((document_id, title, text))
                if len(documents) >= limit:
                    break
            if len(documents) >= limit:
                break

        offset += len(rows)
        if len(rows) < length:
            break

    if not documents:
        raise ValueError(
            "No text found in the dataset API response. Expected passage/context/text "
            "or question-and-answer fields."
        )
    return documents


def index_dataset(dataset_url: str, collection_name: str, limit: int) -> int:
    source_documents = fetch_documents(dataset_url, limit)
    client = chromadb.PersistentClient(path=str(VECTOR_DB_PATH))
    collection = client.get_or_create_collection(
        name=collection_name,
        embedding_function=local_embedding_function(),
    )

    ids = []
    texts = []
    metadatas = []
    for row_id, title, text in source_documents:
        stable_id = hashlib.sha256(
            f"{dataset_url}:{row_id}:{text}".encode("utf-8")
        ).hexdigest()
        ids.append(stable_id)
        texts.append(text)
        metadatas.append(
            {
                "source": dataset_url,
                "title": title[:500] or "History",
                "row_id": row_id,
            }
        )

    print(f"Creating local embeddings for {len(texts)} history passages...")
    collection.upsert(ids=ids, documents=texts, metadatas=metadatas)
    indexed_ids = set(ids)
    existing_ids = collection.get(include=[])["ids"]
    stale_ids = [item_id for item_id in existing_ids if item_id not in indexed_ids]
    if stale_ids:
        collection.delete(ids=stale_ids)
    print(f"Indexed {collection.count()} passages in '{collection_name}'.")
    return collection.count()


def main() -> None:
    parser = argparse.ArgumentParser(
        description="Create local Chroma embeddings from a Hugging Face dataset-server rows API."
    )
    parser.add_argument("--dataset-url", default=DEFAULT_DATASET_URL)
    parser.add_argument("--collection", default=DEFAULT_COLLECTION)
    parser.add_argument("--limit", type=int, default=100)
    args = parser.parse_args()

    if not re.fullmatch(r"[A-Za-z0-9_-]{1,63}", args.collection):
        parser.error("Collection names may contain only letters, numbers, underscores, and hyphens.")
    if args.limit < 1:
        parser.error("--limit must be at least 1.")
    index_dataset(args.dataset_url, args.collection, args.limit)


