class ChatRequest(BaseModel):
    prompt: str
    search_mode: Literal["local", "mixed", "web"] = "local"
    search_web: bool = False
    collection: Literal["combat_aircraft", "history_sample"] = COLLECTION_NAME


class DatasetIndexRequest(BaseModel):
    collection: Literal["combat_aircraft", "history_sample"]


def ensure_dataset_indexed(collection_name: str) -> int:
    client = chromadb.PersistentClient(path=str(VECTOR_DB_PATH))
    collections = {collection.name: collection for collection in client.list_collections()}
    collection = collections.get(collection_name)
    if collection is not None and collection.count() > 0:
        return collection.count()

    if collection_name == DEFAULT_COLLECTION:
        index_dataset(DEFAULT_DATASET_URL, DEFAULT_COLLECTION, limit=100)
    elif collection_name == COLLECTION_NAME:
        build_offline_database()
    else:
        raise ValueError(f"Unsupported dataset: {collection_name}")

    client = chromadb.PersistentClient(path=str(VECTOR_DB_PATH))
    indexed = {collection.name: collection for collection in client.list_collections()}
    collection = indexed.get(collection_name)
    if collection is None or collection.count() == 0:
        raise ValueError(f"Dataset '{collection_name}' produced no indexed passages.")
    return collection.count()


def local_context(prompt: str, collection_name: str = COLLECTION_NAME) -> str:
    client = chromadb.PersistentClient(path=str(VECTOR_DB_PATH))
    collections = {collection.name: collection for collection in client.list_collections()}
    collection = collections.get(collection_name)
    if collection is None or collection.count() == 0:
        try:
            ensure_dataset_indexed(collection_name)
        except (httpx.HTTPError, OSError, ValueError, requests.RequestException, RuntimeError) as error:
            raise HTTPException(
                status_code=503,
                detail=f"Could not prepare local dataset '{collection_name}': {error}",
            ) from error
    try:
        collection = client.get_collection(
            name=collection_name,
            embedding_function=local_embedding_function(),
        )
    except ValueError as error:
        raise HTTPException(
            status_code=503,
            detail=f"Index '{collection_name}' could not be created in {VECTOR_DB_PATH}.",
        ) from error

    if collection.count() == 0:
        raise HTTPException(
            status_code=503,
            detail=f"Index '{collection_name}' is empty. Embed data before asking questions.",
        )

    try:
        results = collection.query(
            query_texts=[prompt],
            n_results=min(collection.count(), 10),
            include=["documents", "metadatas", "distances"],
        )
    except (httpx.HTTPError, OSError, ValueError) as error:
        raise HTTPException(
            status_code=503,
            detail=(
                "Local embeddings are unavailable. Chroma may need internet access "
                f"to download its all-MiniLM-L6-v2 model on first use: {error}"
            ),
        ) from error
    documents = results["documents"][0]
    metadatas = results["metadatas"][0]
    context = []
    seen_pages = set()
    for document, metadata in zip(documents, metadatas):
        if not document:
            continue
        page = metadata.get("page") if metadata else None
        if page is not None and page in seen_pages:
            continue
        if page is not None:
            seen_pages.add(page)
            context.append(f"[Page {page}]\n{document}")
        elif metadata and metadata.get("title"):
            context.append(f"[{metadata['title']}]\n{document}")
        else:
            context.append(document)
        if len(context) == 4:
            break
    if not context:
        raise HTTPException(status_code=503, detail="No relevant book passages were retrieved.")
    return "\n\n".join(context)


def format_web_results(results: list[dict[str, str]]) -> str:
    return "\n\n".join(
        f"[{index}] {result['title']}\n"
        f"URL: {result['url']}\n"
        f"Published: {result.get('published') or 'date not provided'}\n"
        f"Evidence: {result['content']}"
        for index, result in enumerate(results, start=1)
    )


