BASE_DIR = Path(__file__).resolve().parent
API_DATASETS_PATH = BASE_DIR / "api_datasets.json"
SUPPORTED_EMBEDDING_MODEL = "all-MiniLM-L6-v2"
TEXT_FIELDS = ("text", "content", "passage", "context", "answer", "description")
