    if not isinstance(vectors, list) or len(vectors) != len(texts):
        raise ValueError(f"Embedding model '{model_name}' returned an invalid vector batch.")
    converted = []
    dimension = None
    for vector in vectors:
        if hasattr(vector, "tolist"):
