    elif dataset.database.type == "pinecone":
        results = _query_pinecone(dataset, vector, limit)
    else:
        results = _query_weaviate(dataset, vector, limit)
    return [
        result
        for result in results
        if isinstance(result.get("text"), str) and result["text"].strip()
    ]

