        ) from error
    return {"collection": request.collection, "indexed": True, "items": count}


@app.post("/ask")
async def ask_ai(request: ChatRequest):
    prompt = request.prompt.strip()
    if not prompt:
        return {"reply": "Please enter a question."}

    mode = "web" if request.search_web and request.search_mode == "local" else request.search_mode
    web_results = []
    if mode in {"mixed", "web"}:
        try:
            web_results = search_online(prompt)
        except requests.RequestException as error:
            raise HTTPException(status_code=503, detail=f"Live web search failed: {error}") from error
        except ValueError as error:
            raise HTTPException(status_code=502, detail=str(error)) from error

    dataset_ids = request.dataset_ids if request.dataset_ids is not None else [request.collection]
    if len(set(dataset_ids)) != len(dataset_ids):
        dataset_ids = list(dict.fromkeys(dataset_ids))
    local_evidence = ""
    if mode in {"local", "mixed"}:
        if not dataset_ids:
            raise HTTPException(status_code=422, detail="Select at least one local dataset.")
        local_evidence = (
            local_context(prompt, dataset_ids[0])
            if len(dataset_ids) == 1
            else local_context_for_datasets(prompt, dataset_ids)
        )
    web_evidence = format_web_results(web_results) if web_results else ""
    if mode == "mixed":
        context = f"LOCAL DATASET EVIDENCE:\n{local_evidence}\n\nLIVE WEB SEARCH RESULTS:\n{web_evidence}"
    elif mode == "web":
        context = f"LIVE WEB SEARCH RESULTS:\n{web_evidence}"
    else:
        context = local_evidence

    try:
        return {
            "reply": generate_reply(
                prompt,
                context,
                mode == "web",
                dataset_ids[0] if len(dataset_ids) == 1 else ",".join(dataset_ids),
                mixed=mode == "mixed",
            ),
            "sources": web_results,
        }
    except requests.RequestException as error:
        raise HTTPException(
            status_code=503,
            detail=f"Chat model unavailable at {CHAT_URL}: {error}",
        ) from error
    except (IndexError, KeyError, ValueError) as error:
        raise HTTPException(status_code=502, detail=f"Invalid response from chat model: {error}") from error


