def _save_hf_imports(manifest: dict[str, dict]) -> None:
    path = _hf_import_manifest_path()
    path.parent.mkdir(parents=True, exist_ok=True)
    temporary_path = path.with_suffix(".json.tmp")
    temporary_path.write_text(json.dumps(manifest, indent=2), encoding="utf-8")
    temporary_path.replace(path)


def _huggingface_rows_url(dataset: str, config: str, split: str) -> str:
