@app.post("/datasets/huggingface/import")
async def import_huggingface_dataset(request: HuggingFaceImportRequest):
    dataset_id = request.dataset.strip()
    config = request.config.strip()
    split = request.split.strip()
    dataset_url = _huggingface_rows_url(dataset_id, config, split)
    identifier = hashlib.sha256(
        f"{dataset_id}\n{config}\n{split}".encode("utf-8")
    ).hexdigest()[:12]
    local_id = f"hf_{identifier}"
    collection_name = f"huggingface_{identifier}"
    try:
        documents, data_fields = index_hf_dataset.fetch_documents(
            dataset_url,
            limit=request.limit,
            api_key=request.api_key.strip() if request.api_key else None,
            include_format=True,
        )
        data_format = "JSON rows"
        if data_fields:
            data_format += f" · fields: {', '.join(data_fields[:20])}"
        count = index_hf_dataset.index_dataset(
            dataset_url,
            collection_name,
            limit=request.limit,
            source_documents=documents,
            metadata_extra={
                "origin": "huggingface_dataset_api",
                "dataset_id": dataset_id,
                "embedding_model": "all-MiniLM-L6-v2",
            },
        )
    except (
        httpx.HTTPError,
        ImportError,
        OSError,
        ValueError,
        requests.RequestException,
        RuntimeError,
    ) as error:
        raise HTTPException(
            status_code=502,
            detail=f"Could not validate, download, and embed Hugging Face dataset '{dataset_id}': {error}",
        ) from error

    manifest = _load_hf_imports()
    manifest[local_id] = {
        "name": dataset_id,
        "source_id": dataset_id,
        "config": config,
        "split": split,
        "collection": collection_name,
        "items": count,
        "data_format": data_format,
        "embedding_model": "all-MiniLM-L6-v2",
        "origin": "Hugging Face dataset API",
        "indexed": True,
    }
    try:
        _save_hf_imports(manifest)
    except OSError as error:
        raise HTTPException(
            status_code=500,
            detail=f"Dataset was embedded but its local catalog could not be saved: {error}",
        ) from error
    return {
        "dataset_id": local_id,
        "name": dataset_id,
        "indexed": True,
        "items": count,
        "database_collection": collection_name,
        "embedding_model": "all-MiniLM-L6-v2",
        "data_format": data_format,
        "origin": "Hugging Face dataset API",
        "config": config,
        "split": split,
    }


