                return _clean(prefix)
            break
    return ""


def _bing_content(snippet: str) -> str:
    cleaned = (snippet or "").strip()
    if not cleaned:
        return ""
    published = _extract_bing_published(cleaned)
    if published:
        if re.search(r"(?is)^Published\s*:\s*" + re.escape(published), cleaned):
