def _load_hf_imports() -> dict[str, dict]:
    manifest_path = _hf_import_manifest_path()
    if not manifest_path.exists():
        return {}
    try:
        manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as error:
        raise HTTPException(status_code=500, detail=f"Could not read Hugging Face dataset catalog: {error}") from error
    if not isinstance(manifest, dict):
        raise HTTPException(status_code=500, detail="Hugging Face dataset catalog must be a JSON object.")
    return manifest


