    if available:
        try:
            response = requests.get(f"{server_root}/slots", timeout=3)
            response.raise_for_status()
            slots = response.json()
            if isinstance(slots, list):
                contexts = [
                    (slot.get("n_prompt_tokens_cache"), slot.get("n_ctx"))
