def _query_dataset_passages(prompt: str, collection_name: str) -> list[dict]:
    imported_dataset = (
        _load_hf_imports().get(collection_name)
        or _load_text_imports().get(collection_name)
    )
    if imported_dataset:
        query_collection = imported_dataset["collection"]
    else:
        query_collection = collection_name
    if query_collection not in {COLLECTION_NAME, DEFAULT_COLLECTION} and not imported_dataset:
        try:
            dataset = get_registry_dataset(collection_name, API_DATASETS_PATH)
            if dataset.mode == "text":
                ensure_dataset_indexed(collection_name)
            results = query_api_dataset(dataset, prompt)
        except (
            httpx.HTTPError,
            ImportError,
            OSError,
            ValueError,
            requests.RequestException,
            RuntimeError,
        ) as error:
            raise HTTPException(
                status_code=503,
                detail=f"Could not query API dataset '{collection_name}': {error}",
            ) from error
        passages = []
        for rank, result in enumerate(results):
            metadata = result.get("metadata") or {}
            title = metadata.get("title") or dataset.name
            passages.append({
                "text": result["text"],
                "citation": title,
                "score": float(result.get("score", 0.0) or 0.0),
                "rank": rank,
            })
        if not passages:
            raise HTTPException(
                status_code=503,
                detail=f"API dataset '{collection_name}' returned no matching text.",
            )
        return passages[:5]

    client = chromadb.PersistentClient(path=str(VECTOR_DB_PATH))
    collections = {collection.name: collection for collection in client.list_collections()}
    collection = collections.get(query_collection)
    if collection is None or collection.count() == 0:
        try:
            ensure_dataset_indexed(collection_name)
        except (httpx.HTTPError, OSError, ValueError, requests.RequestException, RuntimeError) as error:
            raise HTTPException(
                status_code=503,
                detail=f"Could not prepare local dataset '{collection_name}': {error}",
            ) from error
    try:
        collection = client.get_collection(
            name=query_collection,
            embedding_function=local_embedding_function(),
        )
    except ValueError as error:
        raise HTTPException(
            status_code=503,
            detail=f"Index '{query_collection}' could not be created in {VECTOR_DB_PATH}.",
        ) from error

    if collection.count() == 0:
        raise HTTPException(
            status_code=503,
            detail=f"Index '{query_collection}' is empty. Embed data before asking questions.",
        )

    try:
        results = collection.query(
            query_texts=[prompt],
            n_results=min(collection.count(), 10),
            include=["documents", "metadatas", "distances"],
        )
    except (httpx.HTTPError, OSError, ValueError) as error:
        raise HTTPException(
            status_code=503,
            detail=(
                "Local embeddings are unavailable. Chroma may need internet access "
                f"to download its all-MiniLM-L6-v2 model on first use: {error}"
            ),
        ) from error
    documents = results["documents"][0]
    metadatas = results["metadatas"][0]
    passages = []
    seen_pages = set()
    distances = results.get("distances", [[]])[0]
    for rank, (document, metadata) in enumerate(zip(documents, metadatas)):
        if not document:
            continue
        distance = distances[rank] if rank < len(distances) else None
        score = 1 / (1 + max(float(distance), 0.0)) if distance is not None else 0.0
        page = metadata.get("page") if metadata else None
        if page is not None and page in seen_pages:
            continue
        if page is not None:
            seen_pages.add(page)
            citation = f"Page {page}"
        elif metadata and metadata.get("title"):
            citation = metadata["title"]
        else:
            citation = ""
        if imported_dataset and citation and citation != imported_dataset["name"]:
            citation = f"{imported_dataset['name']}: {citation}"
        passages.append({
            "text": document,
            "citation": citation,
            "score": score,
            "rank": rank,
        })
        if len(passages) == 4:
            break
    if not passages:
        raise HTTPException(status_code=503, detail="No relevant book passages were retrieved.")
    return passages


def _format_passages(passages: list[dict]) -> str:
    return "\n\n".join(
        f"[{passage['citation']}]\n{passage['text']}"
        if passage["citation"]
        else passage["text"]
        for passage in passages
    )


def local_context_for_datasets(prompt: str, dataset_ids: list[str]) -> str:
    unique_ids = list(dict.fromkeys(dataset_ids))
    imported_datasets = {**_load_hf_imports(), **_load_text_imports()}
    for dataset_id in unique_ids:
        if dataset_id in {COLLECTION_NAME, DEFAULT_COLLECTION} or dataset_id in imported_datasets:
            continue
        try:
            get_registry_dataset(dataset_id, API_DATASETS_PATH)
        except ValueError as error:
            raise HTTPException(status_code=422, detail=str(error)) from error

    with ThreadPoolExecutor(max_workers=min(len(unique_ids), 8)) as executor:
        futures = {
            dataset_id: executor.submit(_query_dataset_passages, prompt, dataset_id)
            for dataset_id in unique_ids
        }
        passages = []
        for dataset_id, future in futures.items():
            try:
                dataset_passages = future.result()
            except HTTPException as error:
                raise HTTPException(
                    status_code=error.status_code,
                    detail=f"Dataset '{dataset_id}': {error.detail}",
                ) from error
            passages.extend(dataset_passages)

    passages.sort(key=lambda passage: (-passage["score"], passage["rank"]))
    return _format_passages(passages[:10])


