def _search_request(method, url: str, **kwargs):
    for attempt in range(SEARCH_MAX_ATTEMPTS):
        try:
            response = method(url, **kwargs)
        except requests.RequestException:
            if attempt + 1 == SEARCH_MAX_ATTEMPTS:
                raise
