                const formattedReply = escapeHTML(data.reply)
                    .replace(/\*\*(.*?)\*\*/g, '<strong>$1</strong>')
                    .replace(/\n/g, '<br>');

                loadingMessage.replaceChildren();
                const assistantLabel = document.createElement('b');
                assistantLabel.textContent = 'AI Assistant:';
                const reply = document.createElement('div');
                reply.innerHTML = formattedReply;
                loadingMessage.append(assistantLabel, document.createElement('br'), reply);

                if (Array.isArray(data.sources) && data.sources.length) {
                    const sourceHeading = document.createElement('b');
                    sourceHeading.textContent = 'Live web sources';
                    const sourceList = document.createElement('ol');
                    sourceList.className = 'source-list';
                    sourceList.setAttribute('aria-label', 'Live web sources used for this answer');
                    for (const source of data.sources) {
                        const item = document.createElement('li');
                        const link = document.createElement('a');
                        link.href = source.url;
                        link.target = '_blank';
                        link.rel = 'noopener noreferrer';
                        link.textContent = source.title;
                        const date = document.createElement('small');
                        date.textContent = source.published
                            ? ` — ${source.published}`
                            : ' — publication date not provided';
                        item.append(link, date);
                        sourceList.appendChild(item);
                    }
                    loadingMessage.append(sourceHeading, sourceList);
                }
                if (appSettings.showStats && data.metrics) {
                    const stats = document.createElement('div');
                    stats.className = 'generation-stats';
                    const metricLabels = [
                        ['Speed', data.metrics.tokens_per_second == null ? 'n/a' : `${Number(data.metrics.tokens_per_second).toFixed(1)} tok/s`],
                        ['Tokens', data.metrics.total_tokens == null
                            ? 'n/a'
                            : `${data.metrics.prompt_tokens ?? '?'} in / ${data.metrics.completion_tokens ?? '?'} out (${data.metrics.total_tokens} total)`],
                        ['KV reused', data.metrics.kv_cache_reused_tokens == null
                            ? 'not reported'
                            : `${data.metrics.kv_cache_reused_tokens} tokens`],
                        ['Time', data.metrics.duration_seconds == null ? 'n/a' : `${data.metrics.duration_seconds}s`]
                    ];
                    for (const [label, value] of metricLabels) {
                        const item = document.createElement('span');
                        item.textContent = `${label}: ${value}`;
                        stats.appendChild(item);
                    }
                    loadingMessage.appendChild(stats);
                }
                chatbox.scrollTop = chatbox.scrollHeight;

            } catch (error) {
                console.error("Network Stack Error:", error);
                const failureText = `Request failed: ${error.message} (Endpoint: ${serverBaseURL}/ask)`;
                document.getElementById(loadingId).textContent = failureText;
                chatMessages.push({ role: 'assistant', content: failureText });
                storeChat();
                chatbox.scrollTop = chatbox.scrollHeight;
            }
        }
    </script>

