        function appendDatasetOption(container, id, dataset, selected) {
            const label = document.createElement('label');
            label.className = 'dataset-option';
            const checkbox = document.createElement('input');
            checkbox.type = 'checkbox';
            checkbox.name = 'dataset-source';
            checkbox.value = id;
            checkbox.checked = selected.has(id);
            const details = document.createElement('span');
            const stamp = `${dataset.scope === 'api' ? 'API' : 'LOCAL'} • ${(dataset.type || 'text').toUpperCase()}`;
            const title = document.createElement('strong');
            title.className = 'dataset-watermark';
            title.textContent = stamp;
            const name = document.createElement('span');
            name.className = 'dataset-name';
            name.textContent = dataset.dataset_name || dataset.name || id;
            const status = document.createElement('span');
            status.className = 'dataset-status';
            status.textContent = [
                dataset.scenario || 'General reference',
                dataset.source || dataset.endpoint || '',
                dataset.items ? `${dataset.items} passages` : ''
            ].filter(Boolean).join(' · ');
            details.append(title, name, status);
            label.append(checkbox, details);
            container.appendChild(label);
            checkbox.addEventListener('change', () => {
                try {
                    localStorage.setItem(SOURCES_KEY, JSON.stringify(selectedDatasetIds()));
                } catch (error) {
                    console.warn('Could not save selected data sources:', error);
                }
                if (checkbox.checked && dataset.mode === 'text' && !dataset.indexed) {
                    prepareLocalDataset(id, status).catch((error) => {
                        status.textContent = `Could not prepare API dataset: ${error.message}`;
                    });
                }
                updateSelectedSourceCount();
            });
        }

        async function refreshDatasetStatus() {
            const response = await fetch(`${serverBaseURL}/datasets/status`);
            if (!response.ok) throw new Error(`HTTP ${response.status}`);
            const data = await response.json();
            datasetStatuses.clear();
            for (const [id, dataset] of Object.entries(data.datasets || {})) {
                datasetStatuses.set(id, dataset);
            }
            const available = new Set(Object.keys(data.datasets || {}));
            const selected = new Set([
                ...selectedDatasetIds(),
                ...savedSources
            ].filter((id) => available.has(id)));
            for (const [scope, targetId] of [['local', 'local-dataset-options'], ['api', 'api-dataset-options']]) {
                const container = document.getElementById(targetId);
                container.replaceChildren();
                for (const kind of ['text', 'embedded', 'pages']) {
                    for (const dataset of data.groups?.[scope]?.[kind] || []) {
                        appendDatasetOption(container, dataset.dataset_id || dataset.id, dataset, selected);
                    }
                }
                if (!container.childElementCount) {
                    const empty = document.createElement('span');
                    empty.className = 'dataset-empty';
                    empty.textContent = 'No validated datasets yet';
                    container.appendChild(empty);
                }
            }
            updateSelectedSourceCount();
        }

        async function prepareLocalDataset(collection, statusElement) {
            if (datasetPreparation.has(collection)) return datasetPreparation.get(collection);
            const task = (async () => {
                statusElement.textContent = 'Preparing configured API dataset…';
