    )
    source = dataset.data_url or dataset.database.url
    record = {
        "dataset_id": dataset.id,
        "dataset_name": dataset.name,
        "source": source,
        "type": "embedded" if dataset.mode == "preembedded" else "text",
        "scope": "api",
