    }
    for dataset in datasets.values():
        scope = "api" if dataset["source_type"] == "ONLINE_API" else "local"
        kind = dataset["data_type"].lower()
        groups[scope][kind].append(dataset)
    return {"datasets": datasets, "groups": groups}

import hashlib
